l,"description":"Broadline foodservice distributor (U.S. Foodservice) acquired from Royal Ahold with KKR.","sector":null,"hq":null,"status":"realized","invested_year":2007,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/historic-investments","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Van Kampen","slug":"van-kampen","domain":null,"description":null,"sector":null,"hq":null,"status":"realized","invested_year":1993,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/historic-investments","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"VWR International","slug":"vwr-international","domain":null,"description":"Sold to Madison Dearborn Partners.","sector":null,"hq":null,"status":"realized","invested_year":2004,"exit_year":2007,"fund_name":null,"source_url":"https://www.cdr.com/historic-investments","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"WESCO Distribution","slug":"wesco-distribution","domain":null,"description":null,"sector":null,"hq":null,"status":"realized","invested_year":1994,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/historic-investments","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"WGM Safety","slug":"wgm-safety","domain":null,"description":null,"sector":null,"hq":null,"status":"realized","invested_year":1981,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/historic-investments","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Atalian","slug":"atalian","domain":null,"description":"Facilities management company; CD&R Fund XI and affiliates made a binding offer to acquire it to combine with OCS.","sector":"Industrials & Business Services","hq":null,"status":null,"invested_year":null,"exit_year":null,"fund_name":"CD&R Fund XI","source_url":"https://www.cdr.com/news/cdr-to-acquire-atalian-and-ocs-to-form-a-global-facilities-management-platform","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Fort Dearborn","slug":"fort-dearborn","domain":null,"description":"Label manufacturer acquired from Advent International and combined with Multi-Color Corporation.","sector":"Industrials & Business Services","hq":null,"status":null,"invested_year":2021,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/news/cdr-completes-combination-of-fort-dearborn-and-multi-color-corporation-to-create-global-leader-in-prime-label-industry","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Construction Supply Group","slug":"construction-supply-group","domain":null,"description":"Distributor of specialty concrete and masonry accessories, combined with White Cap (CD&R funds 65% of the combined company).","sector":"Industrials & Business Services","hq":null,"status":null,"invested_year":2020,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/news/cdr-to-combine-hd-supplys-white-cap-business-with-construction-supply-group","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Paradigm Precision","slug":"paradigm-precision","domain":null,"description":"Provider of complex machining, fabrications and assemblies for engine manufacturers; combined with Whitcraft into Pursuit Aerospace.","sector":"Industrials & Business Services","hq":null,"status":null,"invested_year":2023,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/news/cdr-and-greenbriar-equity-complete-acquisitions-to-create-a-new-leading-supplier-to-the-aerospace-industry-called-pursuit-aerospace","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Whitcraft Group","slug":"whitcraft-group","domain":null,"description":"Manufacturer of precision flight-critical aerospace components; combined with Paradigm into Pursuit Aerospace.","sector":"Industrials & Business Services","hq":null,"status":null,"invested_year":2023,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/news/cdr-and-greenbriar-equity-complete-acquisitions-to-create-a-new-leading-supplier-to-the-aerospace-industry-called-pursuit-aerospace","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Atrium Windows & Doors","slug":"atrium-windows-and-doors","domain":null,"description":"Manufacturer of residential windows and doors, acquired with Golden Gate Capital and merged with Ply Gem.","sector":"Industrials & Business Services","hq":null,"status":null,"invested_year":2018,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/news/ply-gem-holdings-inc-enters-into-a-definitive-agreement-to-be-acquired-by-clayton-dubilier-rice","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"UDG Healthcare","slug":"udg-healthcare","domain":null,"description":"Healthcare advisory, communications, commercial, clinical and packaging services platform; taken private and combined with Huntsworth.","sector":"Healthcare","hq":null,"status":null,"invested_year":2021,"exit_year":null,"fund_name":null,"source_url":"https://www.cdr.com/news/simon-tinkler-partner-at-clifford-chance-appointed-senior-legal-advisor-to-cdr","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null}],"deals":[]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'Clayton, Dubilier & Rice, LLC'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'Clayton, Dubilier & Rice, LLC'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'cdr-inc.com redirects to cdr.com: current holdings from /portfolio (?display=list, as of Aug 2026) plus each /portfolio/<slug> page from sitemap_portfolio.xml (sector, region, year, website); all past investments from /historic-investments (CD&R''s ''complete list''); exits, funds and combined add-on platforms from the 352 /news releases in sitemap_news.xml, plus Wikipedia. status current = on /portf', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'Clayton, Dubilier & Rice', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
